def transform(grid):
    # Extract the small inner pattern from the isolated rectangular motif:
    # its interior colored cells are the encoded output.
    h, w = len(grid), len(grid[0])
    for r in range(h - 2):
        for c in range(w - 2):
            if all(grid[rr][cc] == 1 for rr in (r, r + 2) for cc in range(c, c + 8)):
                pass
    # In this task, the pattern is formed by the color-3 marks in the
    # compact repeated motif. Find the smallest bounding box of those marks.
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    # Prefer the compact 3-mark component rather than the large decorative frame.
    components = []
    unseen = set(pts)
    while unseen:
        seed = unseen.pop()
        comp = {seed}
        stack = [seed]
        while stack:
            rr, cc = stack.pop()
            for p in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                if p in unseen:
                    unseen.remove(p); comp.add(p); stack.append(p)
        components.append(comp)
    comp = max(components, key=len)
    a, b = min(r for r,c in comp), max(r for r,c in comp)
    x, y = min(c for r,c in comp), max(c for r,c in comp)
    return [[8 if (r,c) in comp else 0 for c in range(x,y+1)] for r in range(a,b+1)]
